import re
import unittest
import xml.etree.ElementTree as ET
from pathlib import Path

TARGET = Path(__file__).resolve().parent / "city-skyline.svg"
REQUIRED_IDS = {"sky", "sun", "hills", "hills-silhouette", "skyline",
                "skyline-silhouette", "blocks", "blocks-silhouette", "windows",
                "river", "waterline", "reflections", "blocks-reflection", "birds"}
DEPTH_ORDER = ["sky", "hills", "skyline", "blocks", "river"]
SILHOUETTES = ["hills-silhouette", "skyline-silhouette", "blocks-silhouette"]


def tag(el):
    return el.tag.split("}")[-1]


def num(value, default=None):
    try:
        return float(str(value).strip())
    except (TypeError, ValueError):
        return default


def pairs(points):
    """Every (x, y) in a points= attribute, whatever the separators."""
    parts = [p for p in re.split(r"[\s,]+", (points or "").strip()) if p]
    vals = [num(p) for p in parts]
    vals = [v for v in vals if v is not None]
    return list(zip(vals[0::2], vals[1::2]))


def rgb(value):
    m = re.match(r"^#([0-9a-fA-F]{6})$", (value or "").strip())
    if not m:
        return None
    h = m.group(1)
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def saturation(value):
    """Plain HSV saturation: how far the colour is from grey."""
    parts = rgb(value)
    if parts is None:
        return None
    hi, lo = max(parts), min(parts)
    return 0.0 if hi == 0 else (hi - lo) / float(hi)


class Acceptance(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = TARGET.read_text(encoding="utf-8")
        cls.root = ET.fromstring(cls.raw)
        cls.byid = {}
        cls.order = {}
        for i, el in enumerate(cls.root.iter()):
            ident = el.get("id")
            if ident and ident not in cls.byid:
                cls.byid[ident] = el
                cls.order[ident] = i
        box = (cls.root.get("viewBox") or "").replace(",", " ").split()
        cls.vb = [num(v) for v in box] if len(box) == 4 else [None] * 4

    # --- helpers ---------------------------------------------------------
    def node(self, ident):
        el = self.byid.get(ident)
        self.assertIsNotNone(el, "missing id=%s" % ident)
        return el

    def points(self, ident):
        pts = pairs(self.node(ident).get("points"))
        self.assertGreaterEqual(len(pts), 3,
                                "id=%s must carry a numeric points= outline" % ident)
        return pts

    def top(self, ident):
        return min(y for _, y in self.points(ident))

    def base(self, ident):
        return max(y for _, y in self.points(ident))

    def waterline(self):
        el = self.node("waterline")
        for attr in ("y", "y1", "cy"):
            v = num(el.get(attr))
            if v is not None:
                return v
        pts = pairs(el.get("points"))
        if pts:
            return min(y for _, y in pts)
        self.fail("waterline needs a numeric y, y1 or cy")

    # --- structure -------------------------------------------------------
    def test_root_is_svg_with_viewbox(self):
        self.assertEqual(tag(self.root), "svg")
        self.assertNotIn(None, self.vb, "viewBox must have 4 numbers")
        w, h = self.vb[2], self.vb[3]
        self.assertTrue(w and w >= 100, "viewBox width too small: %r" % w)
        self.assertTrue(h and h >= 100, "viewBox height too small: %r" % h)

    def test_required_ids_present(self):
        missing = sorted(REQUIRED_IDS - set(self.byid))
        self.assertEqual(missing, [], "missing required ids: %s" % missing)

    def test_no_external_references(self):
        for el in self.root.iter():
            for key, value in el.attrib.items():
                if key.split("}")[-1] in ("href", "src") and re.match(r"\s*(https?:)?//", value or ""):
                    self.fail("external reference in %s: %s" % (tag(el), value))
        self.assertNotIn("@import", self.raw)
        self.assertFalse(re.search(r"url\(\s*['\"]?(https?:)?//", self.raw),
                         "external url() reference")

    def test_no_script_or_raster(self):
        kinds = {tag(el) for el in self.root.iter()}
        self.assertNotIn("script", kinds, "SVG must not contain <script>")
        self.assertNotIn("image", kinds, "SVG must be vector only, no <image>")
        self.assertNotIn("foreignObject", kinds)

    # --- depth, measured -------------------------------------------------
    def test_layers_are_painted_back_to_front(self):
        """Document order IS the depth order: sky, hills, skyline, blocks, river."""
        for ident in DEPTH_ORDER:
            self.node(ident)
        seq = [self.order[i] for i in DEPTH_ORDER]
        self.assertEqual(seq, sorted(seq),
                         "layers out of depth order, document positions %s for %s"
                         % (seq, DEPTH_ORDER))

    def test_further_layers_have_lower_silhouettes(self):
        """Atmospheric depth: the further back a layer is, the lower its skyline
        sits on screen, so its topmost y is larger."""
        tops = [self.top(s) for s in SILHOUETTES]
        for (a, ta), (b, tb) in zip(zip(SILHOUETTES, tops), zip(SILHOUETTES[1:], tops[1:])):
            self.assertGreater(ta, tb,
                               "%s tops out at y=%.1f, not below %s at y=%.1f"
                               % (a, ta, b, tb))

    def test_nearer_layers_stand_on_lower_ground(self):
        """The ground plane recedes upward: each layer's base is lower on screen
        than the base of the layer behind it."""
        bases = [self.base(s) for s in SILHOUETTES]
        for (a, ba), (b, bb) in zip(zip(SILHOUETTES, bases), zip(SILHOUETTES[1:], bases[1:])):
            self.assertLess(ba, bb,
                            "%s is based at y=%.1f, not above %s at y=%.1f"
                            % (a, ba, b, bb))

    def test_colour_desaturates_with_distance(self):
        sats = []
        for ident in SILHOUETTES:
            fill = self.node(ident).get("fill")
            s = saturation(fill)
            self.assertIsNotNone(s, "%s needs a literal #rrggbb fill, got %r" % (ident, fill))
            sats.append(s)
        for (a, sa), (b, sb) in zip(zip(SILHOUETTES, sats), zip(SILHOUETTES[1:], sats[1:])):
            self.assertLess(sa, sb,
                            "%s (saturation %.3f) must be flatter than %s (%.3f)"
                            % (a, sa, b, sb))

    # --- the scene -------------------------------------------------------
    def test_sky_is_a_graded_dusk(self):
        ref = None
        for el in self.node("sky").iter():
            m = re.match(r"url\(\s*#([^)\s]+)\s*\)", (el.get("fill") or "").strip())
            if m:
                ref = m.group(1)
                break
        self.assertIsNotNone(ref, "the sky must be filled with a gradient")
        grad = self.byid.get(ref)
        self.assertIsNotNone(grad, "gradient #%s is never defined" % ref)
        stops = [c for c in grad.iter() if tag(c) == "stop"]
        self.assertGreaterEqual(len(stops), 3,
                                "a dusk sky needs at least 3 gradient stops, got %d" % len(stops))

    def test_the_sun_is_setting(self):
        sun = self.node("sun")
        cy = num(sun.get("cy"), num(sun.get("y")))
        self.assertIsNotNone(cy, "sun needs a numeric cy or y")
        ridge = self.top("hills-silhouette")
        self.assertGreater(cy, self.vb[1] + 0.25 * self.vb[3],
                           "the sun sits too high in the frame for dusk: y=%.1f" % cy)
        self.assertLess(cy, ridge,
                        "a setting sun must still sit above the hills' ridge y=%.1f, got %.1f"
                        % (ridge, cy))

    def test_near_block_windows_are_lit(self):
        found = []

        def walk(el, inherited):
            fill = el.get("fill") or inherited
            if tag(el) == "rect":
                found.append(fill)
            for child in el:
                walk(child, fill)

        windows = self.node("windows")
        walk(windows, windows.get("fill"))
        self.assertGreaterEqual(len(found), 40,
                                "a lit near block needs >=40 windows, got %d" % len(found))
        warm = [f for f in found if rgb(f) and rgb(f)[0] > rgb(f)[2]]
        self.assertGreaterEqual(len(warm), 0.8 * len(found),
                                "lit windows must read warm (red above blue): %d of %d"
                                % (len(warm), len(found)))
        low, high = self.top("blocks-silhouette"), self.waterline()
        for el in windows.iter():
            if tag(el) != "rect":
                continue
            y = num(el.get("y"))
            self.assertIsNotNone(y, "every window needs a numeric y")
            self.assertTrue(low <= y <= high,
                            "window at y=%.1f is outside the near block band %.1f-%.1f"
                            % (y, low, high))

    def test_the_reflection_is_the_near_block_mirrored(self):
        water = self.waterline()
        src = self.points("blocks-silhouette")
        ref = self.points("blocks-reflection")
        tol = max(2.0, 0.01 * self.vb[3])
        self.assertLessEqual(abs(self.base("blocks-silhouette") - water), tol,
                             "the near block must stand at the waterline y=%.1f" % water)
        self.assertEqual(len(ref), len(src),
                         "the reflection must mirror the silhouette point for point: %d vs %d"
                         % (len(ref), len(src)))
        for i, ((sx, sy), (rx, ry)) in enumerate(zip(src, ref)):
            self.assertLessEqual(abs(rx - sx), tol,
                                 "reflection point %d drifted sideways: %.1f vs %.1f" % (i, rx, sx))
            self.assertLessEqual(abs((sy + ry) / 2.0 - water), tol,
                                 "reflection point %d is not mirrored about y=%.1f: %.1f and %.1f"
                                 % (i, water, sy, ry))

    def test_reflections_stay_below_the_waterline(self):
        water = self.waterline()
        ys = []
        for el in self.node("reflections").iter():
            self.assertNotEqual(tag(el), "path",
                                "reflection geometry must be measurable: no <path> in #reflections")
            ys.extend(y for _, y in pairs(el.get("points")))
            for attr in ("y", "cy", "y1", "y2"):
                v = num(el.get(attr))
                if v is not None:
                    ys.append(v)
        self.assertTrue(ys, "no measurable geometry inside #reflections")
        self.assertGreaterEqual(min(ys), water - 0.5,
                                "a reflection reaches y=%.1f, above the waterline y=%.1f"
                                % (min(ys), water))

    def test_birds_fly_above_the_skyline(self):
        flock = [el for el in self.node("birds").iter() if pairs(el.get("points"))]
        self.assertGreaterEqual(len(flock), 3, "a flock needs at least 3 birds, got %d" % len(flock))
        ceiling = self.top("skyline-silhouette")
        for el in flock:
            lowest = max(y for _, y in pairs(el.get("points")))
            self.assertLess(lowest, ceiling,
                            "a bird dips to y=%.1f, below the mid skyline top y=%.1f"
                            % (lowest, ceiling))


if __name__ == "__main__":
    unittest.main()
